def report_work_hours(file_name):
    #Khatwa 1.1: Ihit al-kod alladhi qad yulqi istithna fi block try
    try :
        #Khatwa 1.1.1: Iftah al-milaff wa aamil ma'a kulla sater fi al-milaff        
        myfile = open( file_name, "r")
        for line in myfile:
            tokens = line.split()
            name = tokens[0]
            total = 0.0;
            for i in range(1, len(tokens)) :
                try :
                    total += float(tokens[i])
                except ValueError:
                    print("Khata fi al saa.")
            print("Majmu saat al amal li " + name  + " = " + str(total))
